package io.github.mangi.eta.agent.model

import io.github.mangi.eta.agent.memory.AgentMemoryContext
import io.github.mangi.eta.agent.skill.SkillContext
import io.github.mangi.eta.agent.roleplay.RoleplayRunContext
import io.github.mangi.eta.agent.terminal.TerminalExecutionContext
import org.json.JSONArray
import org.json.JSONObject

/** Зберіть системні обмеження, історію та поточний вхід користувача для кожного запуску.*/
internal object AgentPromptBuilder {
    fun buildInitialMessages(
        config: AgentModelClient.ModelConfig,
        prompt: String,
        images: List<AgentModelClient.ModelImage>,
        history: List<AgentModelClient.ConversationMessage>,
        skillContext: SkillContext,
        memoryContext: AgentMemoryContext = AgentMemoryContext.DISABLED,
        rootAvailable: Boolean = false,
        roleplayContext: RoleplayRunContext? = null,
        executionContext: TerminalExecutionContext? = null,
    ): JSONArray {
        val messages = buildSystemMessages(config, skillContext, memoryContext, rootAvailable, roleplayContext, executionContext)
        history.forEach { item ->
            runCatching { AgentConversationCodec.toJsonObject(item) }.getOrNull()?.let(messages::put)
        }
        messages.put(AgentConversationCodec.userMessage(prompt, images))
        return messages
    }

    /**
     * Системне підказка є початком префікса запиту. Будь-яка зміна байтів призведе до втрати всієї подальшої історії з кешу.
     * Таким чином, тут наведено лише стабільні факти в межах сеансу: Root розрізняє лише «авторизований/неавторизований», прогрес виявлення, причини збою тощо.
     * Миттєвий стан повідомляється моделі за допомогою інструментального результату check_root без введення системної підказки.
     */
    fun buildSystemMessages(
        config: AgentModelClient.ModelConfig,
        skillContext: SkillContext,
        memoryContext: AgentMemoryContext,
        rootAvailable: Boolean,
        roleplayContext: RoleplayRunContext? = null,
        executionContext: TerminalExecutionContext? = null,
    ): JSONArray {
        val messages = JSONArray()
        if (roleplayContext == null && config.systemPrompt.isNotBlank()) {
            messages.put(systemMessage(config.systemPrompt))
        }
        messages.put(
            systemMessage(
                (if (roleplayContext == null) {
                    ""
                } else {
                    "відповідно доназадПродовженнялюдейрічналаштуватиЗвичайноплатитипотік，ВиконатидобрезаразРеальністьпризначитиобслуговуваннягодинатакожзберегтиутримуватирігколірзтілочасткаімовагаз；заразРеальністьТримайтеробитиПасПасколивпередможевикористовуватипрацюватиІнструментВиконатидобре。" +
                        "${AgentConversationToolCatalog.READ_HISTORY} поверненняповерненнянемаєможеЗміназОригіналпочатокВиконатидобрекалендарісторії；використовуватипобутовібудуватипорядокназадзпростомистецтвазаколивпередначальникавнизмистецтвасерединазбудуватипорядокакторський складфільмдлядозволяють，немаєздатнийвикористовуватиОригіналфайлисправавилучитишпилькапростомистецтвабудуватипорядок。" +
                        "районточкавіртуальнийструктурадрамаПрихильністьівикористовуватипобутовіхочутьпроситиззаразРеальністьпризначитиобслуговування，немаєпучокдрамаПрихильністьсерединазрухатисяробитиколистативженавчатиправильноззаразРеальністьТримайтеробити，немаєпучокпрацюватиІнструментсправжнійРеальністьвузолфруктизмінитиНапишітьстативіртуальнийструктурарічРеальність；"
