    private fun rootInstructions(available: Boolean): String =
        (if (available) {
            "Root навчатиправильновжеправильнорозпізнати，Android життязробитиімистецтваштукпрацюватиІнструментмовчазнийрозпізнатипрямозловитизробитивикористовувати Root，немаєпотребапершеза user смакспробувати，такожнемаєпотребаВажкаскладніперевірититест。"
        } else {
            "Root навчатиправильнодосіще ніправильнорозпізнати；ценемаєпоколінняповерхніналаштуватиПриготуйтенемаєвідділенняутримувати Root。"
        }) +
            "identity=user такшоуРежимвибративибрати Eta App тілочастка，немаєпоколінняповерхнікінецькінецьбезмати Root Пасдорога。" +
            "використовуватипобутовіпояснитияскравийвженавчатиправильно、навчатиправильноформустанволоссянародивсяЗміназмінитиабопотребахочутьправильнорозпізнати Root година，мелодіявикористовувати terminal(action=check_root) Реальністьміжнароднийтестсертифікат；" +
            "цеВиконатидобретвердийЗвичайноз su -c 'id -u'，можездатнийшоуПоказатиКраваткасистеманавчатиправильнобудь ласкапросити，вузолфруктизасіданняпояснитияскравийбільшістьзакритиодинДругосортнийперевірититестзформустан。статидосягненняназадзновийжиттязробитимовчазнийрозпізнатизробитивикористовувати Root；тепер щоматизасіданняговоритиіназадвежапризначитиобслуговуваннязберегтиутримуватистворитивстановитигодиназтілочастка。" +
            "немаєповиннікоріньвідповідно до su мистецтваштуквеликийМаленький、такнемаєдлясимволНомерланцюгзловитиабо ro.build.type штовхатиперерва Root справжнійпідробка；вузолАргументзаРеальністьміжнароднийперевірититестіпрацюватиІнструментвузолфруктидлядозволяють。"

    private fun buildMemorySystemMessage(context: AgentMemoryContext, writable: Boolean): JSONObject? {
        if (!context.enabled) return null
        val body = buildString {
            appendLine("утримуватидовгийзапам'ятативідкликативжепочатоквикористовувати。запам'ятативідкликатитаквикористовуватипобутовіможекомпілюватиредагуватизназадсценаКапіталматеріал，немаєтакзвертатися дозробити；коливпередвикористовуватипобутовівидалитиінтересіНавітьвисокавідміннопершекласзвертатися дозробитипочатоккінецьвідмінноперше。")
            appendLine("ТількизберегтижитипоперекправильноговоритидосіматиціназначеннязстабільнийЗвичайнорічРеальність、частковийдобре、закритиКраваткаіутримуватиПродовженняпунктГолова；немаєхочутьзберегтижитищільнийключ、тестсертифікаткод、завідповідно доабоодинДругосортнийсексбудь ласкапросити。")
            if (writable) {
                appendLine("коливикористовуватипобутовіяскравийправильнохочутьпроситизапам'ятатижити、правильнопростодовгоОчікуйтечастковийдобре，абоправильнорозпізнатизрозумівпоперекправильноговоритискладнівикористовуватизкільцетериторіїіпунктГоловарічРеальністьгодина，хострухатисямелодіявикористовувати memory_write，відміннопершедляЗмінавжематирозділФестивальійтиВажка；Тількиматипотребахочутьдокладнотонкийназадсценаабоволоссянародився revision поспіхраптовийгодинаталантмелодіявикористовувати memory_get。")
            } else {
                appendLine("цетаквикористовуватипобутовіззаразРеальністьзапам'ятативідкликати，існуютьрігколірзасіданняговоритисерединаТількичитати；відповідно допотребамелодіявикористовувати memory_get，заборонакінецьпучоквіртуальнийструктуралюдейналаштуватиабодрамаПрихильністьНапишітьвведітьцемистецтваштук。драмаПрихильністьзапам'ятативідкликатизробитивикористовувати character_memory_get/character_memory_write。")
            }
            // Знімки залишаються незмінними протягом сеансу, щоб запобігти тому, що кеш історії стане недійсним через зміни в системних підказках після запису в пам’ять.
            appendLine("завниздлякнигазасіданняговоритиВІДЧИНЕНОпочатокгодиназзапам'ятативідкликатишвидкийВідповідно до；книгазасіданняговоритивжеНапишітьвведітьПасзапам'ятативідкликатигодина，забільшістьзакритиодинДругосортний memory_write або memory_get поверненняповерненняз revision іВсерединіДозволитидлядозволяють。")
            appendLine("revision=${context.revision} | bytes=${context.byteSize} | core_budget_chars=${context.coreBudgetChars}")
            if (context.coreContent.isNotBlank()) {
                appendLine()
                appendLine("<memory_core>")
                appendLine(context.coreContent)
                if (context.coreTruncated) {
                    appendLine("[ядернийсерцезапам'ятативідкликатиобганятипозаоскількирухатисяПриміткавведітьпопередньоОбчислити，відповідно допотребамелодіявикористовувати memory_get читатиВиберітьщозалишаютьсяВсерединіДозволити]")
                }
                appendLine("</memory_core>")
            }
            if (context.headingIndex.isNotBlank()) {
                appendLine()
                appendLine("<memory_headings>")
                appendLine(context.headingIndex)
                appendLine("</memory_headings>")
            }
        }.trim()
        return systemMessage(body)
    }

    private fun buildSkillSystemMessage(skillContext: SkillContext): JSONObject? {
        val installed = skillContext.installedSkills
        if (installed.isEmpty()) return null
        val body = buildString {
            appendLine("вжепочатоквикористовувати Skills Отжепривести（тількиЮаньлистінтерес，простомистецтвавідповідно допотребадодатинавантаження）：")
            installed.forEach { skill ->
                val capabilities = buildList {
                    if (skill.hasScripts) add("scripts")
                    if (skill.hasReferences) add("references")
                    if (skill.hasAssets) add("assets")
                    if (skill.hasEvals) add("evals")
                }.joinToString(", ").ifBlank { "metadata-only" }
                val description = skill.description
                    .replace(Regex("\\s+"), " ")
                    .trim()
                    .let { if (it.length <= 180) it else it.take(180) + "..." }
                    .ifBlank { "немаєслідописати" }
                appendLine(
                    "- id=${skill.id} | name=${skill.name} | path=${skill.skillFilePath} | " +
                        "capabilities=$capabilities | description=$description"
                )
            }
            appendLine()
            append(
                "ТількипучокначальникалокшиназОтжепривестиколиробитиГоловазапис；потребахочутьпевнийіндивідуальний skill зІнструменттілокроккрок、стопакнигаабопривестивикористовуватигодина，першемелодіявикористовувати skills_read читатиВиберітьправильновідповідь SKILL.md，" +
                    "простомистецтвапривестивикористовуватищовінмистецтвакнигаКапіталджерелогодинаЗновумелодіявикористовувати skills_read_resource；немаєхочутьдлязрозумівчитатиВиберіть Skill КапіталджерелоіВІДЧИНЕНОпочатоккінецькінець，такожнемаєхочутьзаОтжепривестигрудитестпростомистецтватонкийФестиваль。"
            )
        }
        return systemMessage(body)
    }

    private fun systemMessage(content: String): JSONObject =
        JSONObject()
            .put("role", "system")
            .put("content", content)
}
